  function normalise(raw) {
    let v = raw.trim();
    if (!v) return null;
    if (!/^https?:\/\//i.test(v)) v = 'https://' + v;
    try { return new URL(v); } catch (e) { return null; }
  }

  function titleFrom(u) {
    // Assumption: derive a readable title from the address until real titles exist.
    let path = decodeURIComponent(u.pathname).replace(/\/+$/,'');
    let last = path.split('/').filter(Boolean).pop();
    if (last) {
      last = last.replace(/[-_]+/g, ' ').replace(/\.[a-z0-9]+$/i,'');
      return last.charAt(0).toUpperCase() + last.slice(1);
    }
    return u.hostname.replace(/^www\./,'');
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const u = normalise(input.value);
    if (!u) {
      hint.textContent = "Hmm, that doesn't look like a link yet.";
      return;
    }
    hint.textContent = 'Saved.';
    if (empty) empty.remove();

    const item = document.createElement('div');
    item.className = 'item';
    item.innerHTML =
      '<span class="domain-chip">' + u.hostname.replace(/^www\./,'') + '</span>' +
      '<div class="title"></div>' +
      '<a class="url" target="_blank" rel="noopener"></a>' +
      '<div class="meta"><span>Saved just now</span></div>';
    item.querySelector('.title').textContent = titleFrom(u);
    const a = item.querySelector('.url');
    a.textContent = u.href;
    a.href = u.href;

    list.insertBefore(item, list.firstChild);
    input.value = '';
    input.focus();
    setTimeout(function(){ if (hint.textContent === 'Saved.') hint.textContent = ''; }, 2000);
  });

  document.body.setAttribute('data-harness-ready', 'true');
</script>
